// Some portions generated by Claude
package org.eclipse.rdf4j.workbench.commands;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.impl.RepositoryBNode;
import org.junit.jupiter.api.Test;

/**
 * A remote server's blank nodes arrive with a transport envelope as their ID; the Types and Named Graphs lists show,
 * filter and sort them by the repository's own ID.
 */
class BrowseListNamesTest {

	private static final Value NEGOTIATED = RepositoryBNode.fromNegotiatedResult("rdf4jbo1_s_YWJj", "abc", true);

	@Test
	void aNegotiatedBlankNodeIsFilteredByItsRepositoryId() {
		assertThat(BrowseList.matching("abc").test(NEGOTIATED)).isTrue();
		assertThat(BrowseList.matching("rdf4j").test(NEGOTIATED)).isFalse();
	}

	@Test
	void aNegotiatedBlankNodeIsSortedByItsRepositoryId() {
		Value iri = SimpleValueFactory.getInstance().createIRI("http://example.org/b");
		List<Value> values = new ArrayList<>(List.of(iri, NEGOTIATED));

		values.sort(BrowseList.BY_NAME);

		assertThat(values).containsExactly(NEGOTIATED, iri);
	}
}
